create or replace view public.master_executive_indicators with (security_invoker=true) as select d.tenant_id,d.company_id,d.company_name,d.company_status,d.account_balance,d.payable_open,d.receivable_open,d.overdue_open,(d.account_balance-d.payable_open)::numeric(14,2) net_cash_after_payables,case when d.payable_open>0 then round((d.account_balance/d.payable_open)*100,2) else null end cash_coverage_percent,d.card_credit_limit,d.card_committed,d.card_available,d.card_open_statements,d.card_overdue_statements,d.active_employees,d.pending_documents,d.pending_payroll_occurrences,d.work_count,d.engineering_contract_value,d.engineering_measured_net,d.engineering_contract_balance,d.engineering_production_value,d.engineering_actual_revenue,d.engineering_outstanding,d.engineering_overdue,d.engineering_future_revenue,case when d.engineering_contract_value>0 then round((d.engineering_measured_net/d.engineering_contract_value)*100,2) else 0 end engineering_measured_percent,case when d.engineering_contract_value>0 then round((d.engineering_production_value/d.engineering_contract_value)*100,2) else 0 end engineering_production_percent,d.attention_items,d.critical_items,d.projected_cash_deficit,case when d.critical_items>0 or d.projected_cash_deficit>0 then 'critical' when d.attention_items>0 or d.overdue_open>0 then 'attention' else 'ok' end executive_status from public.master_company_dashboard d;
create or replace view public.master_monthly_trend with (security_invoker=true) as select m.*,sum(m.actual_income-m.actual_expense) over(partition by m.tenant_id,m.company_id order by m.competence_month rows between unbounded preceding and current row)::numeric(14,2) accumulated_actual_result,sum(m.engineering_projected_revenue-m.total_planned_expense) over(partition by m.tenant_id,m.company_id order by m.competence_month rows between unbounded preceding and current row)::numeric(14,2) accumulated_projected_result,lag(m.actual_expense) over(partition by m.tenant_id,m.company_id order by m.competence_month) previous_actual_expense,lag(m.actual_income) over(partition by m.tenant_id,m.company_id order by m.competence_month) previous_actual_income from public.master_company_monthly_dashboard m;
create or replace view public.master_attention_summary with (security_invoker=true) as select tenant_id,company_id,count(*)::integer attention_count,count(*) filter(where status ilike '%overdue%' or status='critical')::integer urgent_count,coalesce(sum(amount) filter(where source_type in ('financial_installment','card_statement','recurrence')),0)::numeric(14,2) financial_attention_amount,count(*) filter(where source_type='hr_employee')::integer hr_attention_count,min(attention_date) oldest_attention_date from public.master_attention_queue group by tenant_id,company_id;
comment on view public.master_executive_indicators is 'Executive indicators and derived status per company.';
comment on view public.master_monthly_trend is 'Monthly trend with accumulated actual and projected results.';
comment on view public.master_attention_summary is 'Consolidated attention indicators per company.';